mapper.select:
select
sub.ID ID, sub.TAB_NUM TAB_NUM, sub.SUB_NAME SUB_NAME, sub.SUB_TYPE SUB_TYPE, sub.SUB_FORM_TYPE SUB_FORM_TYPE,
sub.SUB_WIDTH SUB_WIDTH, sub.SUB_TMP_TYPE SUB_TMP_TYPE, sub.SUB_CHART_TYPE SUB_CHART_TYPE, sub.SUB_DEFUALT SUB_DEFUALT,
sub.STATUS STATUS, sub.CREATE_USER CREATE_USER, sub.CREATE_DEPT CREATE_DEPT, sub.CREATE_TIME CREATE_TIME,
sub.UPDATE_USER UPDATE_USER, sub.UPDATE_TIME UPDATE_TIME, sub.SUB_CHART_CONF SUB_CHART_CONF ,tab.TEMP_NAME
from DIS_POI_SUB sub
left join DIS_POI_TAB tab on sub.TAB_NUM = tab.TAB_NUM
where
1=1


        #{tabNum,jdbcType=VARCHAR}



    and SUB_TYPE in

        #{subType,jdbcType=VARCHAR}




        #{subFormType,jdbcType=VARCHAR}




        #{subTmpType,jdbcType=VARCHAR}




        #{subChartType,jdbcType=VARCHAR}



    and STATUS =#{status,jdbcType=VARCHAR}


    and SUB_NAME like '%' || #{subName} || '%'


    and ID like '%' || #{id} || '%'
